<?php
namespace App\Services\AI;
use App\Support\Database;use App\Support\TenantContext;
final class ServiceDiscoveryService { public function registerSource(int $serviceId,string $title,string $url,string $authority,string $type='official',float $confidence=1.0):int{$s=Database::pdo()->prepare('INSERT INTO knowledge_sources(tenant_id,service_id,title,url,authority,source_type,discovered_at,confidence,created_at,updated_at) VALUES(?,?,?,?,?,?,NOW(),?,NOW(),NOW())');$s->execute([TenantContext::id(),$serviceId,$title,$url,$authority,$type,$confidence]);return (int)Database::pdo()->lastInsertId();} public function addRequirement(int $sourceId,?int $serviceId,string $text,array $structured=[],float $confidence=1.0):int{$s=Database::pdo()->prepare('INSERT INTO knowledge_requirements(tenant_id,source_id,service_id,requirement_text,structured_json,confidence,created_at) VALUES(?,?,?,?,?,?,NOW())');$s->execute([TenantContext::id(),$sourceId,$serviceId,$text,json_encode($structured),$confidence]);return (int)Database::pdo()->lastInsertId();}}
